from pathlib import Path
import hashlib,importlib.util,json,os,sys,time

base=Path(__file__).parent;repo=Path.cwd();build=base/'d02-gate-build-r1';out=base/'d02-pvp-gates-r1';assert not out.exists();assert json.loads((build/'result.json').read_bytes())['exit']==0
pin=json.loads((build/'source-pin.json').read_bytes());assert all(hashlib.sha256((repo/n).read_bytes()).hexdigest()==h for n,h in pin.items())
