out.mkdir();(out/'prior-budget.original.json').write_bytes(prior);(out/'policy.original.json').write_bytes((base/'d02-gate-policy.before-run-r1.json').read_bytes());binary=build/'build/bin/FantasyCard.Server.Tests/debug';binaries={p.relative_to(binary).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in binary.rglob('*') if p.is_file()};(out/'binary-manifest.original.json').write_text(json.dumps(binaries,indent=2)+'\n')
observations=out/'observations';command=['dotnet',str(binary/'FantasyCard.Server.Tests.dll'),'-noLogo','-noColor','-noAutoReporters','-failSkips','-parallel','none','-reporter','verbose','-method','FantasyCard.Server.Tests.Config.SeasonPublishedPvpGateTests.PublishedLateJoinAndCooldownRespectTheLastBlockedAndFirstAllowedTicks','-trx',str(out/'cases.trx'),'-xml',str(out/'cases.xml')]
handle=dict(parent_pid=os.getpid(),command=command,started_at=time.time(),prior_used=97,planned=3,local_reserve_GiB=2,startup_GiB=1);(out/'started.original.json').write_text(json.dumps(handle,indent=2)+'\n');budget_path.write_text(json.dumps(dict(item='D02',used=97,remaining=203,maximum=300,current_handle=handle),indent=2)+'\n')
spec=importlib.util.spec_from_file_location('guard',repo/'client/tests/fixture_runtime.py');guard=importlib.util.module_from_spec(spec);spec.loader.exec_module(guard);r=None;error=None
try:r=guard.guarded_run(command,env=dict(os.environ,DOTNET_CLI_UI_LANGUAGE='en',DOTNET_CLI_TELEMETRY_OPTOUT='1',FANTASYCARD_RUN_D02_GATE_BOUNDARIES='1',FANTASYCARD_D02_GATE_PRIOR='97',FANTASYCARD_D02_GATE_OUTPUT=str(observations),FANTASYCARD_RUN_D02_REBUILD='',FANTASYCARD_RUN_D02_ROUTES='',FANTASYCARD_RUN_D02_DUELS='',FANTASYCARD_RUN_D01_BOUNDARIES='',FANTASYCARD_RUN_C16_CALIBRATION='',FANTASYCARD_C16_REUSE_PREFLIGHT='',FANTASYCARD_RUN_THEME_COMPARISON='',FANTASYCARD_RUN_B05_MATRIX='',FANTASYCARD_RUN_B05_FINAL_NINE='',FANTASYCARD_TEST_POSTGRES=''),timeout=180,wait_seconds=180)
except Exception as e:error=dict(type=type(e).__name__,error=str(e),output=str(getattr(e,'output','')));(out/'interrupted.original.json').write_text(json.dumps(error,indent=2)+'\n')
if r:(out/'run.original.log').write_text(r.stdout+r.stderr,encoding='utf-8')
p=observations/'attempts.original.jsonl';count=len(p.read_text('utf-8').splitlines()) if p.exists() else 0;assert 0<=count<=3
proof=dict(exit=r.returncode if r else None,error=error,new_actual_matches=count,total_D02_used=97+count,remaining=203-count,source_unchanged=all(hashlib.sha256((repo/n).read_bytes()).hexdigest()==h for n,h in pin.items()),binary_unchanged=all(hashlib.sha256((binary/n).read_bytes()).hexdigest()==h for n,h in binaries.items()),cloud_modified=False,production_modified=False,B05_new_runs=0,C16_new_runs=0,D01_new_runs=0)
(out/'result.json').write_text(json.dumps(proof,indent=2)+'\n');budget_path.write_text(json.dumps(dict(item='D02',used=proof['total_D02_used'],remaining=proof['remaining'],maximum=300,current_handle=None,last_result=str(out/'result.json'),prior_budget=str(out/'prior-budget.original.json')),indent=2)+'\n')
print((r.stdout+r.stderr)[-3500:] if r else json.dumps(error));print(json.dumps(proof));assert r and r.returncode==0 and count==3 and proof['source_unchanged'] and proof['binary_unchanged']
